using System;using System.IO;using System.Reflection;using System.Drawing;using System.Windows.Forms;using LoopFive;
class FxEditingTests {
 static int count;static void A(bool b,string text){if(!b)throw new Exception(text);count++;Console.WriteLine("PASS "+text);}
 static object F(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(o);}
 static void Mouse(Control c,MouseButtons button,bool down){typeof(Control).GetMethod(down?"OnMouseDown":"OnMouseUp",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,new object[]{new MouseEventArgs(button,1,10,10,0)});}
 static string[] Types(Engine e){string[] result=new string[32];for(int i=0;i<16;i++){result[i]=e.Config.InputFx.Slots[i].Type;result[16+i]=e.Config.TrackFx.Slots[i].Type;}return result;}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string prefs=Path.Combine(Storage.DataDirectory,"settings.json");byte[] backup=File.Exists(prefs)?File.ReadAllBytes(prefs):null;try{using(MainForm f=new MainForm()){f.Opacity=0;f.Show();Application.DoEvents();((Timer)F(f,"timer")).Stop();f.Audio.Stop();FxPage page=(FxPage)F(f,"fxPage");for(int section=0;section<2;section++){FxBar bar=(FxBar)F(f,section==0?"inputBar":"trackBar");ChainConfig chain=section==0?f.Engine.Config.InputFx:f.Engine.Config.TrackFx;Button[] edits=(Button[])F(bar,"editSlots");for(int bank=0;bank<4;bank++){chain.Bank=bank;bar.RefreshModel();for(int slot=0;slot<4;slot++){bool on=chain.Slots[bank*4+slot].On;edits[slot].PerformClick();A(((ComboBox)F(page,"section")).SelectedIndex==section&&((ComboBox)F(page,"bank")).SelectedIndex==bank&&((ComboBox)F(page,"slot")).SelectedIndex==slot,"direct edit routes section "+section+" bank "+bank+" slot "+slot);A(chain.Slots[bank*4+slot].On==on,"editing does not toggle effect "+section+"/"+bank+"/"+slot);string[] before=Types(f.Engine);Panel scroll=(Panel)F(page,"scroll");EditorGrid grid=(EditorGrid)scroll.Controls[0];ComboBox type=(ComboBox)grid.GetControlFromPosition(1,1);string newType=chain.Slots[bank*4+slot].Type=="ROBOT"?"PHASER":"ROBOT";type.SelectedItem=newType;string[] after=Types(f.Engine);int selected=section*16+bank*4+slot;bool isolated=after[selected]==newType;for(int i=0;i<32;i++)if(i!=selected)isolated&=before[i]==after[i];A(isolated,"type change affects only chosen slot "+section+"/"+bank+"/"+slot);}}Button[] slots=(Button[])F(bar,"slots");Mouse(slots[2],MouseButtons.Left,true);Mouse(slots[2],MouseButtons.Left,false);((Button)F(bar,"settings")).PerformClick();A(((ComboBox)F(page,"slot")).SelectedIndex==2,"shared Edit remembers selected C for section "+section);chain.Slots[15].Momentary=true;bool active=chain.Slots[15].On;Mouse(slots[3],MouseButtons.Right,true);Mouse(slots[3],MouseButtons.Right,false);A(((ComboBox)F(page,"slot")).SelectedIndex==3&&chain.Slots[15].On==active,"right-click D edits without changing momentary state for section "+section);}
 f.Engine.System.Language="es";f.ApplyLanguage();((FxBar)F(f,"inputBar")).EditSlot(1);Language.Apply(f);Application.DoEvents();using(Bitmap b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(0,0,b.Width,b.Height));b.Save(Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"../../Editar-FX-B-2.6.2.png")));}f.Engine.Dirty=false;f.Close();}Console.WriteLine("TOTAL "+count+" effect editing checks passed");}catch(Exception e){Console.WriteLine("FAIL "+e);Environment.ExitCode=1;}finally{if(backup!=null)File.WriteAllBytes(prefs,backup);else if(File.Exists(prefs))File.Delete(prefs);Language.Set("es");}}
}
